39	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
40	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
41	
42	const BASE_PREMIUM: Record<string, number> = {
43	  sword: 100,
44	  amulet: 60,
45	  staff: 80,
46	  potion: 40,
47	  rune: 25,
48	  moonstone: 25,
49	};
50	
51	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
52	const POLICY_FEE = 5;
53	
54	const COMPONENT_TYPES = ["rune", "moonstone"];
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_BASE_PREMIUM = 60;
57	
58	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
59	
60	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
61	
62	const countOfType = (items: Item[], type: string): number =>
63	  items.filter((item) => item.type === type).length;
64	
65	/**
66	 * Components of one kind are bundled into building blocks of 3, each charged at
67	 * the special block rate; leftovers are charged individually.
68	 */
69	const componentGroupBasePremium = (type: string, count: number): number => {
70	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
71	  const singles = count % BUILDING_BLOCK_SIZE;
72	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
73	};
74	
75	const CURSED_SURCHARGE_RATE = 0.5;
76	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	
79	const surchargeFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
80	
81	const isCursed = (item: Item): boolean => item.cursed === true;
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
84	
85	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
86	const riskMultiplierOf = (item: Item): number =>
87	  surchargeFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
88	  surchargeFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
89	
90	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
91	const mainItemsPremium = (items: Item[]): number =>
92	  sum(
93	    items
94	      .filter((item) => !isComponent(item))
95	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
96	  );
97	
98	/**
99	 * Components are priced per kind, so alike ones can bundle into building blocks.
100	 * Pricing by count means individual risk flags are not visible here — no test covers
101	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
102	 */
103	const componentsPremium = (items: Item[]): number =>
104	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
105	
106	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
107	const riskLoadedPremiumOf = (items: Item[]): number =>
108	  mainItemsPremium(items) + componentsPremium(items);
109	
110	const LOYALTY_DISCOUNT_RATE = 0.2;
111	const LOYALTY_YEARS = 2;
112	
113	const isLoyal = (customer: Customer): boolean => customer.yearsWithMHPCO >= LOYALTY_YEARS;
114	
115	const quote = (items: Item[], customer: Customer): QuoteResult => {
116	  const loyaltyFactor = isLoyal(customer) ? 1 - LOYALTY_DISCOUNT_RATE : 1;
117	  const premiumBeforeFee =
118	    riskLoadedPremiumOf(items) * loyaltyFactor * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
119	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
120	};
