122	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
123	  const results = scenario.steps.map((step) => {
124	    if (step.op === "quote") return quote(step.items, scenario.customer);
125	    throw new Error("claim steps are not implemented yet");
126	  });
127	  return { results };
128	};
